{
  "interface": "Nested extends Array<number | null | undefined | Nested> {}",
  "function": "flatten(input: Nested): number[] {
  const result: number[] = [];
  const stack: Nested[] = [];
  stack.push(input);
  while (stack.length > 0) {
    const current = stack.pop()!;
    if (Array.isArray(current)) {
      for (let i = current.length - 1; i >= 0; i--) {
        stack.push(current[i]);
      }
    } else {
      result.push(current);
    }
  }
  return result;
}",
  "examples": "  const test1 = flatten([0,1,2]);
  console.assert(JSON.stringify(test1) === JSON.stringify([0,1,2]), 'Test 1 failed');
  const test2 = flatten([1,[2,3,4,5,6,7],8]);
  console.assert(JSON.stringify(test2) === JSON.stringify([1,2,3,4,5,6,7,8]), 'Test 2 failed');
  const test3 = flatten([0,2,[[2,3],8,100,4,[[[50]]]],-2]);
  console.assert(JSON.stringify(test3) === JSON.stringify([0,2,2,3,8,100,4,50,-2]), 'Test 3 failed');"
}

